import 'dart:async';
import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../core/theme.dart'; import '../models/app_state.dart'; import '../widgets/task_tile.dart';

class HomeScreen extends StatefulWidget{final AppState state;const HomeScreen({super.key,required this.state});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{
 int tab=0; final uuid=const Uuid();
 @override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:IndexedStack(index:tab,children:[today(),calendar(),analytics(),more()])),floatingActionButton:FloatingActionButton(onPressed:addTask,child:const Icon(Icons.add)),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.today_outlined),selectedIcon:Icon(Icons.today),label:'امروز'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),label:'تقویم'),NavigationDestination(icon:Icon(Icons.insights_outlined),label:'گزارش'),NavigationDestination(icon:Icon(Icons.grid_view_rounded),label:'بیشتر')]));
 Widget today(){final now=DateTime.now();final ts=widget.state.tasks.where((t)=>t.start.year==now.year&&t.start.month==now.month&&t.start.day==now.day).toList()..sort((a,b)=>a.start.compareTo(b.start));final done=ts.where((t)=>t.status=='completed').length,score=ts.isEmpty?0:(done*100~/ts.length);return page('TODAY.LOG','امروزت را اجرا کن.',ListView(children:[Glass(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('DAILY.STATUS',style:TextStyle(fontSize:10,letterSpacing:2,color:Colors.white38)),Text('$score%',style:const TextStyle(fontSize:54,fontWeight:FontWeight.w800)),LinearProgressIndicator(value:score/100,minHeight:7,borderRadius:BorderRadius.circular(10)),const SizedBox(height:18),Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[metric('رضایت','${reviewValue('satisfaction')}%'),metric('تمرکز','${widget.state.focusMinutes}m'),metric('تسک','$done/${ts.length}')])])),const SizedBox(height:15),Glass(child:Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('برنامه امروز',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),IconButton(onPressed:addTask,icon:const Icon(Icons.add))]),if(ts.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Text('برای امروز هنوز تسکی نداری.',style:TextStyle(color:Colors.white38))),...ts.map((t)=>TaskTile(task:t,onToggle:(){t.status=t.status=='completed'?'planned':'completed';widget.state.save();setState((){});},onFocus:()=>focus(t))) ])),const SizedBox(height:15),reviewCard()]));}
 Widget calendar(){final now=DateTime.now(),days=DateUtils.getDaysInMonth(now.year,now.month);return page('CALENDAR','تقویم',GridView.builder(gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,childAspectRatio:1.15,crossAxisSpacing:9,mainAxisSpacing:9),itemCount:days,itemBuilder:(c,i){final d=i+1,n=widget.state.tasks.where((t)=>t.start.year==now.year&&t.start.month==now.month&&t.start.day==d).length;return Glass(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$d',style:const TextStyle(fontWeight:FontWeight.bold)),const Spacer(),Text('$n task',style:const TextStyle(fontSize:11,color:Colors.white38))]));}));}
 Widget analytics(){final all=widget.state.tasks,done=all.where((e)=>e.status=='completed').length,p=all.isEmpty?0:done*100~/all.length;return page('ANALYTICS','گزارش عملکرد',ListView(children:[Row(children:[Expanded(child:Glass(child:metric('Completion','$p%'))),const SizedBox(width:10),Expanded(child:Glass(child:metric('Focus','${widget.state.focusMinutes}m')))]),const SizedBox(height:12),Glass(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('وضعیت کلی',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:18),LinearProgressIndicator(value:p/100),const SizedBox(height:12),Text('$done از ${all.length} تسک انجام شده',style:const TextStyle(color:Colors.white54))]))]));}
 Widget more()=>page('LIFELOG','بیشتر',ListView(children:[menu(Icons.edit_note_rounded,'ژورنال',()=>journal()),menu(Icons.bedtime_outlined,'خواب',()=>sleep()),menu(Icons.repeat_rounded,'عادت‌ها و اهداف',()=>habits()),menu(Icons.inbox_outlined,'Inbox',()=>inbox()),menu(Icons.settings_outlined,'تنظیمات',()=>settings())]));
 Widget page(String eye,String title,Widget child)=>Padding(padding:const EdgeInsets.fromLTRB(16,18,16,8),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(eye,style:const TextStyle(fontSize:10,letterSpacing:2,color:Colors.white38)),Text(title,style:const TextStyle(fontSize:29,fontWeight:FontWeight.w800)),const SizedBox(height:18),Expanded(child:child)]));
 Widget metric(String a,String b)=>Column(children:[Text(a,style:const TextStyle(fontSize:11,color:Colors.white54)),const SizedBox(height:5),Text(b,style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold))]);
 int reviewValue(String k){final r=widget.state.reviews[DateTime.now().toIso8601String().substring(0,10)]??{};return r[k]??0;}
 Widget reviewCard(){return Glass(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Daily Review',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:10),...['satisfaction','mood','energy','focus','productivity','sleepQuality'].map((k){var v=reviewValue(k).toDouble();return StatefulBuilder(builder:(c,set)=>Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(k),Text('${v.round()}%')]),Slider(value:v,max:100,onChanged:(x)=>set(()=>v=x),onChangeEnd:(x){final key=DateTime.now().toIso8601String().substring(0,10);widget.state.reviews[key]??={};widget.state.reviews[key][k]=x.round();widget.state.save();setState((){});})]));})]));}
 Widget menu(IconData i,String t,VoidCallback f)=>Padding(padding:const EdgeInsets.only(bottom:9),child:Glass(padding:EdgeInsets.zero,child:ListTile(leading:Icon(i),title:Text(t),trailing:const Icon(Icons.chevron_left),onTap:f)));
 Future<void> addTask()async{final title=TextEditingController(),note=TextEditingController();DateTime start=DateTime.now(),end=DateTime.now().add(const Duration(hours:1));final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,backgroundColor:const Color(0xFF111622),builder:(c)=>Padding(padding:EdgeInsets.fromLTRB(18,20,18,MediaQuery.of(c).viewInsets.bottom+25),child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('تسک جدید',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:14),TextField(controller:title,decoration:const InputDecoration(labelText:'عنوان')),const SizedBox(height:10),TextField(controller:note,decoration:const InputDecoration(labelText:'توضیحات')),const SizedBox(height:15),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const SizedBox(width:double.infinity,child:Center(child:Text('ذخیره'))))]));if(ok==true&&title.text.trim().isNotEmpty){widget.state.tasks.add(TaskItem(id:uuid.v4(),title:title.text.trim(),note:note.text,start:start,end:end));await widget.state.save();setState((){});}}
 Future<void> focus(TaskItem t)async{final start=DateTime.now();int sec=0;Timer? timer;await showDialog(context:context,barrierDismissible:false,builder:(c)=>StatefulBuilder(builder:(c,set){timer??=Timer.periodic(const Duration(seconds:1),(_){sec=DateTime.now().difference(start).inSeconds;set((){});});return AlertDialog(backgroundColor:const Color(0xFF101521),title:Text(t.title),content:Text('${(sec~/3600).toString().padLeft(2,'0')}:${((sec%3600)~/60).toString().padLeft(2,'0')}:${(sec%60).toString().padLeft(2,'0')}',textAlign:TextAlign.center,style:const TextStyle(fontSize:36,fontWeight:FontWeight.bold)),actions:[FilledButton(onPressed:()=>Navigator.pop(c),child:const Text('پایان Focus'))]);}));timer?.cancel();final mins=(sec/60).ceil();t.focusMinutes+=mins;widget.state.focusMinutes+=mins;await widget.state.save();setState((){});}
 void sheet(String title,Widget body)=>showModalBottomSheet(context:context,isScrollControlled:true,backgroundColor:const Color(0xFF0D121D),builder:(c)=>DraggableScrollableSheet(expand:false,initialChildSize:.82,maxChildSize:.95,builder:(c,sc)=>Padding(padding:const EdgeInsets.all(18),child:ListView(controller:sc,children:[Text(title,style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:16),body])));
 void journal()=>sheet('ژورنال',Column(children:[FilledButton(onPressed:(){final x=TextEditingController();showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('نوشته جدید'),content:TextField(controller:x,maxLines:7),actions:[FilledButton(onPressed:(){widget.state.journal.insert(0,{'text':x.text,'date':DateTime.now().toIso8601String()});widget.state.save();Navigator.pop(c);},child:const Text('ذخیره'))]));},child:const Text('+ نوشته جدید')),...widget.state.journal.map((j)=>ListTile(title:Text(j['text']??''),subtitle:Text(j['date']??'')))]));
 void sleep()=>sheet('خواب',Column(children:[FilledButton(onPressed:(){final active=widget.state.sleep.where((x)=>x['end']==null).toList();if(active.isEmpty)widget.state.sleep.insert(0,{'start':DateTime.now().toIso8601String(),'end':null,'quality':0});else active.first['end']=DateTime.now().toIso8601String();widget.state.save();Navigator.pop(context);},child:Text(widget.state.sleep.any((x)=>x['end']==null)?'بیدار شدم':'خوابیدم')),...widget.state.sleep.map((s)=>ListTile(title:Text(s['end']==null?'در حال خواب':'خواب ثبت‌شده'),subtitle:Text(s['start']??'')))]));
 void habits()=>sheet('عادت‌ها و اهداف',const Text('مدیریت Habit، Streak و Goal در ساختار داده برنامه فعال است؛ UI کامل این بخش در Build بعدی گسترش می‌یابد.'));
 void inbox()=>sheet('Inbox',Column(children:widget.state.tasks.where((t)=>t.category=='Inbox').map((t)=>ListTile(title:Text(t.title))).toList()));
 void settings()=>sheet('تنظیمات',const Column(children:[ListTile(title:Text('Dark Glass'),subtitle:Text('تم پیش‌فرض')),ListTile(title:Text('Privacy'),subtitle:Text('Biometric / PIN scaffold')),ListTile(title:Text('Server'),subtitle:Text('https://yasin.iranvirtual.com/'))]));
}
